def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str):
        # Remove build metadata (everything after +)
        version = version.split('+')[0]

        # Split core version from pre-release
        if '-' in version:
            core, prerelease = version.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = version
            prerelease_parts = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch), prerelease_parts

    def compare_prerelease(pre_a, pre_b):
        # No pre-release means higher precedence
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare pre-release identifiers
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                return -1  # pre_a has fewer identifiers
            if i >= len(pre_b):
                return 1   # pre_b has fewer identifiers

            id_a = pre_a[i]
            id_b = pre_b[i]

            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            if is_num_a and is_num_b:
                # Both numeric: compare numerically
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                if num_a > num_b:
                    return 1
            elif is_num_a:
                # Numeric has lower precedence than non-numeric
                return -1
            elif is_num_b:
                # Non-numeric has higher precedence than numeric
                return 1
            else:
                # Both non-numeric: compare lexically
                if id_a < id_b:
                    return -1
                if id_a > id_b:
                    return 1

        return 0

    core_a, pre_a = parse_version(a)
    core_b, pre_b = parse_version(b)

    # Compare core version
    if core_a < core_b:
        return -1
    if core_a > core_b:
        return 1

    # Core versions are equal, compare pre-release
    return compare_prerelease(pre_a, pre_b)

